import { mountPreview } from './preview.js';
import { apiBase } from './config.js';
// Configuration is generated by the application build, never supplied by messages or query strings.
const preview = mountPreview(document.getElementById('preview'), {
  parentOrigin: window.location.origin,
  apiBase: new URL(apiBase, window.location.origin).href,
});
window.addEventListener('pagehide', () => preview.destroy(), { once: true });
